"""Eight-target comparison; protein is the independent labelled unit."""
from pathlib import Path
import json,hashlib,itertools
import numpy as np,pandas as pd
from sklearn.metrics import roc_auc_score,balanced_accuracy_score,recall_score
ROOT=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 complete=json.loads((ROOT/'completion.json').read_text());assert complete['cases']==141 and complete['frames']==28341,'Incomplete MD cohort';labels=json.loads((ROOT/'config/labels.json').read_text())['labels'];protocol=json.loads((ROOT/'config/protocol.json').read_text());rows=[];sensitivity=[];frame_records=[]
 for rr in complete['records']:
  path=ROOT/'results/poses'/rr['poi']/rr['pose']/'packet.npz';assert sha(path)==rr['packet_sha256'];p=np.load(path);ex=p['nz_exposed_fraction'];bridge=p['bridge'].astype(bool);dist=p['donor_distance_A'];cos=p['sidechain_outward_cosine'];clash=p['target_scaffold_max_overlap_A'];fits=p['anchor_RMSD_A'];assert dist.shape[1]==201 and np.isfinite(dist).all()
  for si,name in enumerate(p['spec_names']):
   scaffold,anchor=str(name).split('__');valid=fits[si]<=3;clear=clash[si]<=.8;near=dist[si]<20;accessible=near&(ex[:,None,:]>=.1);oriented=accessible&(cos[si]>=0);geo=oriented.any(axis=2)&clear[:,None]&valid[:,None];joint=geo&bridge[:,None];row={'poi':rr['poi'],'pose':rr['pose'],'label':labels[rr['poi']],'scaffold':scaffold,'anchor':anchor,'frames':201,'bridge_fraction':float(bridge.mean()),'reach50_fraction':float(p['reach50'].mean()),'distance_only_fraction':float(near.any(axis=2).mean()),'exposed_reachable_fraction':float(accessible.any(axis=2).mean()),'oriented_reachable_fraction':float(oriented.any(axis=2).mean()),'scaffold_compatible_fraction':float(clear.mean()),'anchor_valid_fraction':float(valid.mean()),'geometry_fraction':float(geo.mean()),'productivity_joint_fraction':float(joint.mean()),'conditional_productivity_fraction':float(joint[bridge].mean()) if bridge.any() else np.nan,'maximum_anchor_RMSD_A':float(fits[si].max()),'max_NZ_exposure_fraction':float(ex.max())};rows.append(row)
   if scaffold=='closed_observed' and anchor=='VHL':
    for i in range(201):frame_records.append({'poi':rr['poi'],'pose':rr['pose'],'time_ns':p['times_ns'][i],'bridge':bool(bridge[i]),'scaffold_compatible':bool(clear[i]),'anchor_valid':bool(valid[i]),'primary_joint_fraction_over_endpoints':float(joint[i].mean()),'minimum_lysine_donor_distance_A':float(dist[si,i].min()),'NZ_max_exposed_fraction':float(ex[i].max())})
   for dcut,ecut,ccut in itertools.product([12,16,20,24,30],[.05,.1,.2],[0.,.5]):
    ok=((dist[si]<dcut)&(ex[:,None,:]>=ecut)&(cos[si]>=ccut)).any(axis=2)&clear[:,None]&valid[:,None]&bridge[:,None];sensitivity.append({'poi':rr['poi'],'pose':rr['pose'],'scaffold':scaffold,'anchor':anchor,'distance_A':dcut,'exposure_fraction':ecut,'outward_cosine':ccut,'score':float(ok.mean())})
 poses=pd.DataFrame(rows);numeric=[c for c in poses.select_dtypes('number').columns if c not in ['label','frames']];targets=poses.groupby(['poi','label','scaffold','anchor'],as_index=False)[numeric].mean();targets['poses']=targets.poi.map(poses.groupby('poi').pose.nunique());primary=targets[(targets.scaffold=='closed_observed')&(targets.anchor=='VHL')].copy();assert len(primary)==8 and set(primary.poi)==set(labels);metrics=[]
 for scaffold,anchor in targets[['scaffold','anchor']].drop_duplicates().itertuples(index=False):
  subset=targets[(targets.scaffold==scaffold)&(targets.anchor==anchor)]
  for score in ['bridge_fraction','reach50_fraction','distance_only_fraction','exposed_reachable_fraction','oriented_reachable_fraction','scaffold_compatible_fraction','geometry_fraction','productivity_joint_fraction','conditional_productivity_fraction']:
   v=subset[score].to_numpy();y=subset.label.to_numpy();good=np.isfinite(v);auc=float(roc_auc_score(y[good],v[good])) if len(set(y[good]))==2 else np.nan;pred=v>.0 if score not in ['bridge_fraction','reach50_fraction','scaffold_compatible_fraction'] else v>=.5;ba=float(balanced_accuracy_score(y[good],pred[good]));sens=float(recall_score(y[good],pred[good],zero_division=0));spec=float(recall_score(1-y[good],1-pred[good],zero_division=0));permuted=[]
   if good.all():
    for inds in itertools.combinations(range(8),2):
     yy=np.ones(8,int);yy[list(inds)]=0;permuted.append(roc_auc_score(yy,v))
   pval=float(np.mean(np.abs(np.array(permuted)-.5)>=abs(auc-.5)-1e-12)) if permuted else np.nan;metrics.append({'scaffold':scaffold,'anchor':anchor,'score':score,'targets':int(good.sum()),'AUROC':auc,'balanced_accuracy_descriptive':ba,'sensitivity_descriptive':sens,'specificity_descriptive':spec,'decision_rule':'score>=0.5' if score in ['bridge_fraction','reach50_fraction','scaffold_compatible_fraction'] else 'score>0','exact_two_sided_AUROC_permutation_p':pval,'decision_threshold_validated':False})
 sens=pd.DataFrame(sensitivity).groupby(['poi','scaffold','anchor','distance_A','exposure_fraction','outward_cosine'],as_index=False).score.mean();sens['label']=sens.poi.map(labels);sensmetric=[]
 for key,g in sens.groupby(['scaffold','anchor','distance_A','exposure_fraction','outward_cosine']):sensmetric.append(dict(zip(['scaffold','anchor','distance_A','exposure_fraction','outward_cosine'],key))|{'AUROC':float(roc_auc_score(g.label,g.score)),'targets_with_nonzero_score':int((g.score>0).sum())})
 for name,df in [('pose_scores.tsv',poses),('target_scores_all_variants.tsv',targets),('primary_target_scores.tsv',primary),('metrics.tsv',pd.DataFrame(metrics)),('primary_frame_summary.tsv',pd.DataFrame(frame_records)),('sensitivity_target_scores.tsv',sens),('sensitivity_metrics.tsv',pd.DataFrame(sensmetric))]:df.to_csv(ROOT/'results'/name,sep='\t',index=False)
 receipt={'status':'COMPLETE','cases':141,'frames':28341,'independent_targets':8,'positive_targets':6,'negative_targets':2,'analysis_script_sha256':sha(__file__),'extraction_manifest_sha256':sha(ROOT/'config/execution_manifest.json'),'outputs_sha256':{p.name:sha(p) for p in (ROOT/'results').glob('*.tsv')},'no_GNN_training':True,'hypothetical_negatives_used':False,'primary_score_prespecified':'closed_observed,VHL anchor,20A,exposure>=0.1,outward cosine>=0,max scaffold overlap<=0.8A,anchor fit<=3A,trueVHL bridge<5A','retrospective_historical_chemistry':True};(ROOT/'validation/analysis_receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print(primary[['poi','label','bridge_fraction','productivity_joint_fraction','conditional_productivity_fraction','scaffold_compatible_fraction']].to_string(index=False));print(pd.DataFrame(metrics).query("scaffold=='closed_observed' and anchor=='VHL'")[['score','AUROC']].to_string(index=False))
if __name__=='__main__':main()
